def add_grade(student_grades, assignment_name, grade):
    """Add a grade for a specific assignment to the student's grade book."""
    if assignment_name not in student_grades:
        student_grades[assignment_name] = []

    student_grades[assignment_name].append(grade)

def calculate_average(student_grades):
    """Calculate and return the average grade for the student."""
    if not student_grades:
        return 0

    return sum(grade for assignment_list in student_grades.values() for grade in assignment_list) / len(student_grades)

def main():
    student_grades = {}

    while True:
        assignment_name = input("Enter assignment name (or 'done' to finish): ").strip()

        if assignment_name.lower() == "done":
            break

        grade = float(input(f"Enter grade for {assignment_name}: "))
        add_grade(student_grades, assignment_name, grade)

    average_grade = calculate_average(student_grades)

    print(f"Average grade: {average_grade:.2f}")

if __name__ == "__main__":
    main()
```

This program will prompt the user to enter assignment names and grades until the user enters "done". Then, it calculates and prints the average grade for the student.
